import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays; // Required for Arrays.equals if not using MessageDigest.isEqual

public class ClassX {
    /**
     * Kembalikan true jika sertifikat cocok dengan known_hash.
     * 
     * :param sertifikat: sertifikat
     * :param known_hash: hash yang diketahui
     * :return: true jika sertifikat cocok dengan known_hash
     */
    public boolean checkCertificate(byte[] sertifikat, byte[] known_hash) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] computedHash = digest.digest(sertifikat);
            return MessageDigest.isEqual(computedHash, known_hash);
        } catch (NoSuchAlgorithmException e) {
            // This should ideally not happen as SHA-256 is a standard algorithm
            // Log the error or rethrow as a runtime exception if appropriate for your application
            System.err.println("SHA-256 algorithm not found: " + e.getMessage());
            return false; // Or throw new RuntimeException("SHA-256 not available", e);

