import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Random;

public class ClassX {
    /**
     * Kunin ang mga resulta mula sa kahilingan gamit ang 'results' bilang susi. 
     * Gumawa ng pansamantalang file na may UTF-8 na encoding, 
     * isulat ang unicode string na mga resulta dito, 
     * at ibalik ang landas nito.
     * 
     * @param results Ang mga resulta na isusulat. 
     * @return Ang landas ng pansamantalang file.
     * @throws IOException Kung may error sa paggawa o pagsusulat sa file.
     */
    public String createTempFileWithResults(String results) throws IOException {
        File tempFile = File.createTempFile("tempResults", ".tmp");
        // Ensure the file is deleted when the JVM exits
        tempFile.deleteOnExit();

        try (FileWriter writer = new FileWriter(tempFile, StandardCharsets.UTF_8)) {
            writer.write(results);
        }

        return tempFile.getAbsolutePath();
    }
}
