import java.io.*;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Lumikha ng pansamantalang file na may UTF-8 na encoding, isulat ang mga resulta ng unicode string dito, at ibalik ang landas nito.
     *
     * :param results: unicode string
     * :return: landas ng pansamantalang file
     * :throws IOException: kung may error sa paggawa o pagsusulat sa file
     */
    public static String createTempFileWithUtf8(String results) throws IOException {
        File tempFile = File.createTempFile("tempUnicode", ".txt");
        tempFile.deleteOnExit(); // Optional: Delete the file when the JVM exits

        try (FileOutputStream fos = new FileOutputStream(tempFile);
             OutputStreamWriter osw = new OutputStreamWriter(fos, StandardCharsets.UTF_8)) {
            osw.write(results);
        }

        return tempFile.getAbsolutePath();
    }
}
