import java.io.File;
import java.io.IOException;

public class ClassX {

    /**
     * Elimina l'immagine dal percorso fornito nella directory corrente se esiste.
     * 
     * @param path Il percorso dell'immagine da eliminare.
     * @return {@code true} se l'immagine è stata eliminata con successo o non esisteva, {@code false} altrimenti.
     */
    public boolean deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            // Invalid path provided
            return false;
        }

        File imageFile = new File(path);

        if (imageFile.exists()) {
            // The file exists, attempt to delete it
            return imageFile.delete();
        } else {
            // The file does not exist, so there's nothing to delete.
            // We can consider this a "success" in terms of the desired end state (file not present).
            return true;
        }
    }
}
