```java
import java.io.File;
import java.io.IOException;

public class ClassX {

    /**
     * 如果存在，请从当前目录中删除给定路径的图像。
     * 
     * @param path 要删除的图像路径。
     */
    public void deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            System.err.println("Image path cannot be null or empty.");
            return;
        }

        File imageFile = new File(path);

        if (imageFile.exists()) {
            if (imageFile.delete()) {
                System.out.println("Image deleted successfully: " + path);
            } else {
                System.err.println("Failed to delete image: " + path);
            }
        } else {
            System.out.println("Image does not exist at path: " + path);
        }
    }
}
