```java
import java.io.File;
import java.io.IOException;

public class ClassX {

    /**
     * 如果存在，请从当前目录中删除给定路径的图像。
     * 
     * @param path 要删除的图像路径。
     */
    public void deleteImage(String path) {
        File imageFile = new File(path);

        if (imageFile.exists()) {
            try {
                if (imageFile.delete()) {
                    System.out.println("Image deleted successfully: " + path);
                } else {
                    System.err.println("Failed to delete image: " + path + ". It might be in use or permissions are insufficient.");
                }
            } catch (SecurityException e) {
                System.err.println("Security error while attempting to delete image " + path + ": " + e.getMessage());
            }
        } else {
            System.out.println("Image not found at path: " + path);
        }
    }
}
