     * Verwyder die beeld vanaf die gegewe pad in die huidige gids as dit bestaan.
     * 
     * @param pad Die pad van die beeld wat verwyder moet word.
     */
    public void removeImage(String pad) {
        if (pad == null || pad.trim().isEmpty()) {
            System.err.println("Fout: Die pad kan nie leeg wees nie.");
            return;
