import java.io.File;
import java.io.IOException;

public class ClassX {

    /**
     * מחק את התמונה מהנתיב הנתון בתיקייה הנוכחית אם היא קיימת.
     * <p>
     * Deletes the image from the given path in the current directory if it exists.
     *
     * @param path The path of the image to delete.
     * @return {@code true} if the file was successfully deleted or did not exist, {@code false} otherwise.
     */
    public boolean deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            System.err.println("Path cannot be null or empty.");
            return false;
        }

        File fileToDelete = new File(path);

        if (fileToDelete.exists()) {
            if (fileToDelete.delete()) {
                System.out.println("File deleted successfully: " + path);
                return true;
            } else {
                System.err.println("Failed to delete file: " + path);
                // Possible reasons: permissions, file is open by another process, etc.
                return false;
            }
        } else {
            System.out.println("File does not exist, no deletion needed: " + path);
            return true; // File doesn't exist, so the "deletion" goal is met.
        }
    }
}
