import java.util.regex.*;

public class ClassX {
    /**
     * 检查是否包含 'www.example.com/' 或 'beta.example.com/'。
     * 
     * @param query: 要检查的查询
     * @return: 如果查询有效，则返回 '搜索结果：<query>'，否则返回 '未找到结果：<query>'
     */
    public String checkQuery(String query) {
        // Define the regex pattern to match "www.example.com/" or "beta.example.com/"
        // The `Pattern.CASE_INSENSITIVE` flag is not needed here as the example strings are lowercase.
        // The `Pattern.LITERAL` flag is not suitable as we need alternation.
        // We need to escape the dots as they are special characters in regex.
        String patternString = "(www|beta)\\.example\\.com/";
        Pattern pattern = Pattern.compile(patternString);

        // Create a matcher for the given query
        Matcher matcher = pattern.matcher(query);

        // Check if the pattern is found anywhere in the query string
        if (matcher.find()) {
            return "搜索结果：" + query;
        } else {
            return "未找到结果：" + query;
        }
    }
}
