        File fileToDelete = new File(path);

        if (fileToDelete.exists()) {
            if (fileToDelete.delete()) {
                return "Файл был удален";
            } else {
                // This case might happen if the file exists but is locked or permissions are insufficient
                // The problem statement doesn't explicitly ask for a different message here,
                // so we'll treat it as if it wasn't deleted.
                return "Не удалось удалить файл, хотя он существует."; // Added for clarity, though not strictly required by prompt
            }
        } else {
            return "Файл не существует";
        }
    }
}
