import java.util.*;

public class ClassX {

    // Mock DB
    private static Map<String, String> db = new HashMap<>();

    public void register(String username, String token) {
        db.put(username, token);
    }

    /**
     * نام کاربری و توکن را از بدنه درخواست دریافت کنید و بررسی کنید که آیا ترکیب کاربر/توکن در پایگاه داده وجود دارد یا خیر.  
     * @return: یک شیء JSON با کلید "message" که حاوی پیام وضعیت احراز هویت است:  
     * "احراز هویت موفق" یا "احراز هویت ناموفق" در صورت موفقیت یا شکست، به ترتیب.
     */
    public String authenticate(String username, String token) {
        String message;
        if (db.containsKey(username) && db.get(username).equals(token)) {
            message = "احراز هویت موفق";
        } else {
            message = "احراز هویت ناموفق";
        }
        return "{\"message\": \"" + message + "\"}";
    }
}
