import java.util.*;

public class ClassX {

    // Mock DB
    private static Map<String, String> db = new HashMap<>();

    public void register(String username, String token) {
        db.put(username, token);
    }

    /**
     * İstek gövdesinden "kullanıcı adı" ve "token" alın ve kullanıcı/token kombinasyonunun veritabanında mevcut olup olmadığını kontrol edin.  
     * @return: "Authentication successful" veya "Authentication failed" şeklinde, başarı veya başarısızlık durumuna göre kimlik doğrulama durum mesajını içeren "message" anahtarına sahip bir JSON nesnesi.
     */
    public Map<String, String> authenticate(Map<String, String> requestBody) {
        Map<String, String> response = new HashMap<>();

        String username = requestBody.get("username");
        String token = requestBody.get("token");

        if (username == null || token == null) {
            response.put("message", "Authentication failed: Missing username or token.");
            return response;
        }

        if (db.containsKey(username)) {
            String storedToken = db.get(username);
            if (storedToken.equals(token)) {
                response.put("message", "Authentication successful");
            } else {
                response.put("message", "Authentication failed: Invalid token.");
            }
        }

