```java
import java.util.regex.*;

public class ClassX {
    /**
     * Kontroleer of die invoerstring 'n geldige string is met die volgende formaat: x.y.z (x, y, z is strings)
     * 
     * :param target_string: Die string wat nagegaan moet word
     * :return: Waar as die string geldig is, vals andersins
     */
    public boolean isValidFormat(String target_string) {
        if (target_string == null) {
            return false;
        }
        // The regex `.*\\..*\\..*` matches any string that contains at least two dots,
        // with any characters (or no characters) before, between, and after them.
        // `.` in regex means "any character", so `\.` is used to match a literal dot.
        // `.*` matches zero or more of any character.
        String regex = ".*\\..*\\..*";
        return Pattern.matches(regex, target_string);
    }
}
