import java.util.regex.*;

public class ClassX {
    /**
     * تحقق مما إذا كانت سلسلة الإدخال سلسلة صالحة بالتنسيق التالي: x.y.z (x و y و z هي سلاسل)
     * 
     * :param target_string: السلسلة التي سيتم التحقق منها
     * :return: True إذا كانت السلسلة صالحة، False خلاف ذلك
     */
    public boolean isValidString(String target_string) {
        // Regular expression to match the format x.y.z
        // x, y, and z can be any sequence of characters (non-empty)
        // We use reluctant quantifiers (.*?) to ensure it matches the shortest possible string
        // between dots, though for this specific pattern, greedy (.*) would also work
        // as long as we anchor the pattern.
        // A more precise regex would be: "^[^.]+\\.[^.]+\\.[^.]+$"
        // This ensures that x, y, and z do not contain dots themselves.
        String regex = "^[^.]+\\.[^.]+\\.[^.]+$";

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(target_string);

        return matcher.matches();
    }
}
