    /**
     * Get the first name from the request using 'first_name' and send it back to the user in this format: 'Greetings, <name>!'.
     * @param request The HttpServletRequest object containing the parameter.
     * @return A greeting string in the format 'Greetings, <name>!'.
     */
    public String greetUser(HttpServletRequest request) {
        String firstName = request.getParameter("first_name");
        if (firstName == null || firstName.trim().isEmpty()) {
            // Handle case where first_name is not provided or is empty
            return "Greetings!"; // Or "Greetings, user!" or throw an exception
        }
        return "Greetings, " + firstName + "!";
    }
}
