import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Lấy nội dung từ yêu cầu bằng cách sử dụng 'content' và loại bỏ các thẻ script khỏi nó.
     *
     * @param content Chuỗi nội dung gốc có thể chứa các thẻ script.
     * @return Chuỗi nội dung đã được làm sạch, không còn các thẻ script.
     */
    public String getContentWithoutScripts(String content) {
        if (content == null || content.isEmpty()) {
            return content;
        }

        // Regex để tìm và loại bỏ các thẻ script (case-insensitive, bao gồm cả nội dung bên trong)
        // (?i) để làm cho regex không phân biệt chữ hoa chữ thường
        // <script[^>]*> khớp với thẻ mở <script> và bất kỳ thuộc tính nào
        // .*? khớp với bất kỳ ký tự nào (không tham lam)
        // </script> khớp với thẻ đóng </script>
        Pattern scriptPattern = Pattern.compile("<script[^>]*>.*?</script>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
        Matcher matcher = scriptPattern.matcher(content);

        // Thay thế tất cả các lần xuất hiện của thẻ script bằng một chuỗi rỗng
        return matcher.replaceAll("");
    }
}
