    public String showDashboard() {
        if (session.containsKey("username") && session.get("username") != null && !session.get("username").isEmpty()) {
            // User is authenticated, display dashboard
            return "dashboard.html";
        } else {
            // User is not authenticated, redirect to login
            return "redirect:/login"; // Common convention for HTTP redirect
        }
    }
}
