    public String createTempFileWithResults(String results) throws IOException {
        File tempFile = File.createTempFile("tempResults", ".txt");
        tempFile.deleteOnExit(); // Optional: delete the file when the JVM exits

        try (FileOutputStream fos = new FileOutputStream(tempFile);
