import java.io.*;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Crea un file temporaneo con codifica UTF-8, 
     * scrivi i risultati della stringa unicode in esso, 
     * e restituisci il suo percorso. 
     * @param results: I risultati da scrivere nel file. 
     * @return: Il percorso del file temporaneo dove sono stati salvati i risultati.
     * @throws IOException se si verifica un errore durante la creazione o la scrittura del file.
     */
    public String createTempFileAndWriteResults(String results) throws IOException {
        File tempFile = File.createTempFile("tempResults", ".txt");
        tempFile.deleteOnExit(); // Optional: delete the file when the JVM exits

        try (FileOutputStream fos = new FileOutputStream(tempFile);
             OutputStreamWriter osw = new OutputStreamWriter(fos, StandardCharsets.UTF_8);
             BufferedWriter writer = new BufferedWriter(osw)) {
            writer.write(results);
        }

        return tempFile.getAbsolutePath();
    }
}
