    public Document parseXmlFile(String file_path) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(new File(file_path));
            document.getDocumentElement().normalize(); // Optional: normalize the document
            return document;
        } catch (Exception e) {
            e.printStackTrace(); // Or throw a custom exception
            return null;
        }
    }
}
