import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.File;
import java.io.IOException;

public class ClassX {
    /**
     * Crea un parser XML e analizza il file restituendo l'elemento radice.
     * @param file_path: Il percorso del file XML da analizzare.
     * @return: L'elemento radice del file XML.
     */
    public Document parseXmlFile(String file_path) {
        try {
            File xmlFile = new File(file_path);
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            Document doc = dBuilder.parse(xmlFile);
            doc.getDocumentElement().normalize(); // Optional: Normalize the document
            return doc;
        } catch (ParserConfigurationException e) {
            System.err.println("Error configuring XML parser: " + e.getMessage());
            e.printStackTrace();
        } catch (SAXException e) {
            System.err.println("Error parsing XML file: " + e.getMessage());
            e.printStackTrace();
        } catch (IOException e) {
            System.err.println("Error reading XML file: " + e.getMessage());
            e.printStackTrace();
        }
        return null; // Return null if an error occurs
    }
}
```

