import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.xml.sax.SAXException;
import java.io.File;
import java.io.IOException;

public class ClassX {
    /**
     * قم بإنشاء محلل XML وقم بتحليل الملف وإرجاع العنصر الجذري.
     * @param file_path: المسار إلى ملف XML المراد تحليله.
     * @return: العنصر الجذري لملف XML.
     */
    public Element parseXmlFile(String file_path) throws ParserConfigurationException, SAXException, IOException {
        File xmlFile = new File(file_path);
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
        Document doc = dBuilder.parse(xmlFile);
        doc.getDocumentElement().normalize(); // Optional: Normalize the document
        return doc.getDocumentElement();
    }
}
```

