import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class ClassX {
    /**
     * Crea un vector estático, cifrado utilizando AES y modo CBC. Luego, cifra los datos utilizando el cifrado, añadiendo relleno hasta el tamaño del bloque, y devuélvelo.  
     * @param data: Los datos a cifrar.  
     * @param key: La clave de cifrado.  
     * @return: Los datos cifrados.
     */
    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        // Static IV for demonstration purposes. In a real application, a unique IV should be generated for each encryption.
        byte[] iv = new byte[16]; // 16 bytes for AES block size

        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "AES");

        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivSpec);

        return cipher.doFinal(data);
    }
}
