        this.scores = new ArrayList<>();
    }

    /**
     * Menambahkan skor baru ke dalam daftar.
     *
     * @param score Skor yang akan ditambahkan.
     */
    public void addScore(double score) {
        this.scores.add(score);
    }

    /**
     * Dapatkan skor rata-rata.
     *
     * @return Skor rata-rata dari semua skor yang ditambahkan. Mengembalikan 0.0 jika tidak ada skor.
     */
    public double getAverageScore() {
        if (scores.isEmpty()) {
            return 0.0;
        }

        double sum = 0;
        for (double score : scores) {
            sum += score;
        }

        return sum / scores.size();
    }
}
