public class ClassX {
    /**
     * Obtener la puntuación promedio.
     *
     * @param scores Una lista de puntuaciones.
     * @return La puntuación promedio, o 0.0 si la lista es nula o vacía.
     */
    public double getAverageScore(java.util.List<Integer> scores) {
        if (scores == null || scores.isEmpty()) {
            return 0.0;
        }

        double sum = 0;
        for (Integer score : scores) {
            if (score != null) { // Handle potential null scores in the list
                sum += score;
            }
        }

        return sum / scores.size();
    }
}
