import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Periksa apakah URL masukan adalah URL yang valid dengan format berikut: (www|beta).example.com/
     * 
     * :param url: String URL untuk diperiksa
     * :return: True jika cocok, False jika tidak
     */
    public boolean isValidUrl(String url) {
        // Pola regex untuk (www|beta).example.com/
        // ^ menandakan awal string
        // (www|beta) cocok dengan "www" atau "beta"
        // \\. cocok dengan karakter titik literal
        // example\\.com cocok dengan "example.com"
        // / cocok dengan karakter garis miring literal
        // $ menandakan akhir string
        String regex = "^(www|beta)\\.example\\.com/$";

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(url);

        return matcher.matches();
    }
}
