import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.nio.charset.StandardCharsets;

public class ClassX {

    /**
     * Dapatkan nama file dari permintaan menggunakan 'file_name' dan periksa apakah file tersebut dapat dibuka dengan sukses di jalur yang diberikan dari direktori saat ini.
     *
     * @param fileName Nama file yang akan dibuka.
     * @return Konten file jika file dibuka dengan sukses, null jika tidak.
     */
    public String getFileContent(String fileName) {
        if (fileName == null || fileName.trim().isEmpty()) {
            return null;
        }

        StringBuilder contentBuilder = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new FileReader(fileName, StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                contentBuilder.append(line).append(System.lineSeparator());
            }
            // Remove the last line separator if present
            if (contentBuilder.length() > 0) {
                contentBuilder.setLength(contentBuilder.length() - System.lineSeparator().length());
            }
            return contentBuilder.toString();
        } catch (IOException e) {
            // Log the exception for debugging purposes, but return null as per requirement
            // System.err.println("Error reading file '" + fileName + "': " + e.getMessage());
            return null;
        }
    }
}
