import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Verifica si la URL de entrada es una URL válida con el siguiente formato: (www|beta).example.com/
     * 
     * :param target_url: La URL que se va a verificar
     * :return: Verdadero si la URL es válida, Falso en caso contrario
     */
    public boolean isValidUrl(String target_url) {
        // Expresión regular para (www|beta).example.com/
        // ^ indica el inicio de la cadena
        // (www|beta) coincide con "www" o "beta"
        // \\. coincide con un punto literal
        // example.com coincide con "example.com"
        // / coincide con una barra literal
        // $ indica el final de la cadena
        String regex = "^(www|beta)\\.example\\.com/$";

        // Pattern.matches() es un método de conveniencia que compila la expresión regular
        // y la usa para intentar hacer coincidir la cadena de entrada completa.
        return Pattern.matches(regex, target_url);
    }
}
