import java.util.regex.*;

public class ClassX {
    /**
     * Lấy URL mục từ yêu cầu bằng cách sử dụng 'target_url' và kiểm tra xem nó có hợp lệ theo định dạng này: (www|beta).example.com/
     * 
     * :param targetUrl: Chuỗi URL mục tiêu cần kiểm tra.
     * :return: Trả về True nếu URL hợp lệ, False nếu không.
     */
    public boolean isValidTargetUrl(String targetUrl) {
        // Biểu thức chính quy để kiểm tra định dạng (www|beta).example.com/
        // Lưu ý: Dấu chấm (.) cần được thoát (\\.) vì nó là ký tự đặc biệt trong regex.
        // Dấu gạch chéo (/) không cần thoát trong Java regex, nhưng có thể thoát để rõ ràng hơn nếu muốn.
        String regex = "(www|beta)\\.example\\.com/";

        // Biên dịch biểu thức chính quy
        Pattern pattern = Pattern.compile(regex);

        // Tạo một đối tượng Matcher để so khớp URL đầu vào với mẫu
        Matcher matcher = pattern.matcher(targetUrl);

        // Trả về true nếu toàn bộ chuỗi khớp với mẫu, ngược lại là false
        return matcher.matches();
    }
}
