import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Kunin ang code mula sa kahilingan gamit ang 'code'. Isagawa ito at ibalik ang code.
     *
     * @param code Ang string ng code na isasagawa.
     * @return Ang resulta ng pagpapatupad ng code bilang isang string, o isang mensahe ng error kung may nangyaring exception.
     */
    public String executeAndReturnCode(String code) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // O "nashorn" para sa mas lumang Java, o "graal.js" para sa GraalVM

        try {
            Object result = engine.eval(code);
            return String.valueOf(result);
        } catch (ScriptException e) {
            return "Error executing script: " + e.getMessage();
        } catch (Exception e) {
            return "An unexpected error occurred: " + e.getMessage();
        }
    }
}
