    public String processXmlRequest(String xml_src) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            ByteArrayInputStream input = new ByteArrayInputStream(xml_src.getBytes(StandardCharsets.UTF_8));
            Document doc = builder.parse(input);

            // Normalize the XML structure (optional, but good practice)
            doc.getDocumentElement().normalize();

            // For simplicity, returning the root element's name as requested.
            // In a real application, you might return the Document object itself,
            // or a specific value extracted from it, or serialize it back to a string.
            return doc.getDocumentElement().getNodeName();

        } catch (Exception e) {
            // Log the exception or handle it appropriately
            System.err.println("Error parsing XML: " + e.getMessage());
            return null; // Or throw a custom exception
        }
    }
}
