import java.util.logging.Logger;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Получите имя пользователя из запроса, используя 'name', и запишите его в журнал, если это не администратор.
     *
     * @param userName Имя пользователя, полученное из запроса.
     */
    public void processUserRequest(String userName) {
        if (userName == null || userName.trim().isEmpty()) {
            logger.warning("Received a request with an empty or null user name.");
            return;
        }

        if (!"admin".equalsIgnoreCase(userName)) {
            logger.info("User '" + userName + "' accessed the system.");
        } else {
            logger.fine("Admin user detected, not logging specific access for 'admin'.");
        }
    }
}
