public class ClassX {
    /**
     * Αποκτήστε την τιμή για το δεδομένο κλειδί από το δεδομένο αντικείμενο, έχοντας τα από το αίτημα. Επιστρέψτε την τιμή ως συμβολοσειρά.
     *
     * @param obj Το αντικείμενο από το οποίο θα ανακτηθεί η τιμή.
     * @param key Το κλειδί (όνομα ιδιότητας) της τιμής που θα ανακτηθεί.
     * @return Η τιμή που ανακτήθηκε ως συμβολοσειρά, ή null αν δεν βρεθεί ή προκύψει σφάλμα.
     */
    public String getValue(Object obj, String key) {
        if (obj == null || key == null || key.trim().isEmpty()) {
