import java.util.Map;

public class ClassX {
    /**
     * Get the formatted string from the request using 'formattedStr'.
     * Eval it to a dictionary.
     *
     * @param formattedStr The string to be evaluated as a JavaScript object (dictionary).
     * @return A Java object representing the evaluated JavaScript dictionary, or null if an error occurs.
     * @throws ScriptException If an error occurs during script evaluation.
     */
    public Object getFormattedStringAsDictionary(String formattedStr) throws ScriptException {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("javascript");

        if (engine == null) {
            throw new IllegalStateException("JavaScript engine not found. Ensure Nashorn or GraalJS is available.");
        }

        // Evaluate the string as a JavaScript object
        // The result will typically be a Map<String, Object> if it's a simple JSON-like object
        return engine.eval(formattedStr);
    }
}
