import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;
import java.util.Map;

public class ClassX {
    /**
     * Αποκτήστε τη μορφοποιημένη συμβολοσειρά από το αίτημα χρησιμοποιώντας το 'formattedStr'. Αξιολογήστε την σε ένα λεξικό.
     *
     * @param formattedStr Η μορφοποιημένη συμβολοσειρά που θα αξιολογηθεί ως λεξικό (π.χ. JSON string).
     * @return Ένα Map που αντιπροσωπεύει το λεξικό που προκύπτει από την αξιολόγηση της συμβολοσειράς.
     * @throws ScriptException Εάν υπάρχει σφάλμα κατά την αξιολόγηση της συμβολοσειράς.
     */
    public Map<String, Object> evaluateFormattedStringAsDictionary(String formattedStr) throws ScriptException {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("nashorn"); // Or "graal.js" for newer JDKs, or "javascript"

        if (engine == null) {
            throw new IllegalStateException("JavaScript engine not found. Ensure you are using a JDK that includes Nashorn or GraalJS.");
        }

        // Evaluate the string as a JavaScript object (which Nashorn/GraalJS can convert to a Map)
        // Assuming formattedStr is a valid JSON string or a JavaScript object literal string.
        // For pure JSON, a JSON parser (like Jackson or Gson) would be more robust and performant.
        // This approach is more flexible if formattedStr can be arbitrary JS object literals.
        Object result = engine.eval("(" + formattedStr + ")"); // Wrap in parentheses for object literal evaluation

        if (result instanceof Map) {
            return (Map<String, Object>) result;
        } else {
            throw new ScriptException("Evaluation did not result in a Map. Result type: " + result.getClass().getName());
        }
    }
}
