import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Kry die python kode van die versoek met behulp van 'kode'.
     * Voer dit uit en keer 'Uitgevoer' terug.
     * @param code Die Python kode om uit te voer.
     * @return 'Uitgevoer' as die kode suksesvol uitgevoer is, anders 'Fout'.
     */
    public String executePythonCode(String code) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("python");

        if (engine == null) {
            // Handle case where Python engine is not available (e.g., Jython not in classpath)
            System.err.println("Python ScriptEngine not found. Ensure Jython is in the classpath.");
            return "Fout: Python engine nie gevind nie.";
        }

        try {
            engine.eval(code);
            return "Uitgevoer";
        } catch (ScriptException e) {
            System.err.println("Fout tydens uitvoering van Python kode: " + e.getMessage());
            return "Fout";
        }
    }
}
