public class ClassX {
    /**
     * Haal de python-code op uit het verzoek met 'code'.
     * Voer het uit en geef 'Uitgevoerd' terug.
     */
    public String executePythonCode(String code) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("python"); // Or "jython" if using Jython

        if (engine == null) {
            // Handle the case where the Python engine is not found
            // This might happen if Jython is not on the classpath
            System.err.println("Python ScriptEngine not found. Make sure Jython is on the classpath.");
            return "Fout: Python-engine niet gevonden.";
        }

        try {
            engine.eval(code);
            return "Uitgevoerd";
        } catch (ScriptException e) {
            System.err.println("Fout bij uitvoeren van Python-code: " + e.getMessage());
            return "Fout bij uitvoeren: " + e.getMessage();
        }
    }
}
