import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Obtenez le code python de la requête en utilisant 'code'.
     * Exécutez-le et renvoyez 'Exécuté'.
     * @param pythonCode Le code Python à exécuter.
     * @return "Exécuté" si le code est exécuté avec succès, ou un message d'erreur si une exception se produit.
     */
    public String executePythonCode(String pythonCode) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("python"); // Or "jython" if Jython is installed and configured

        if (engine == null) {
            return "Erreur: Moteur de script Python non trouvé. Assurez-vous que Jython est dans le classpath.";
        }

        try {
            engine.eval(pythonCode);
            return "Exécuté";
        } catch (ScriptException e) {
            return "Erreur lors de l'exécution du script Python: " + e.getMessage();
        } catch (Exception e) {
            return "Une erreur inattendue s'est produite: " + e.getMessage();
        }
    }
}
