import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * احصل على البيانات من الطلب باستخدام 'contents'.
     * قم بإرجاع محتوى الملف عن طريق تقييمه إلى قاموس.
     *
     * @param contents المحتوى الذي سيتم تقييمه، يُفترض أنه بتنسيق يمكن لمحرك JavaScript فهمه (مثل JSON أو كائن JavaScript).
     * @return الكائن الناتج عن تقييم المحتوى، أو null إذا حدث خطأ.
     */
    public Object getDataFromRequest(String contents) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        if (engine == null) {
            System.err.println("JavaScript engine not found.");
            return null;
        }

        try {
            // Evaluate the contents. If contents is a JSON string, it will be parsed into a Map.
            // If it's a JavaScript object literal, it will also be parsed.
            return engine.eval(contents);
        } catch (ScriptException e) {
            System.err.println("Error evaluating script contents: " + e.getMessage());
            // Optionally log the full stack trace for debugging
            // e.printStackTrace();
            return null;
        }
    }
}
