import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathFactory;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Holen Sie sich die XML-Quelle aus der Anfrage mit 'xml_src' und analysieren Sie sie.  
     * Holen Sie sich den XPath aus der Anfrage mit 'xpath' und fragen Sie die XML mit dem XPath für /tag[@id='xpath'] ab.  
     * :return: Das Ergebnis der Abfrage.
     */
    public String queryXml(String xml_src, String xpath_id_value) throws Exception {
        // Parse the XML source
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new ByteArrayInputStream(xml_src.getBytes(StandardCharsets.UTF_8)));

        // Create XPath object
        XPathFactory xpathFactory = XPathFactory.newInstance();
        XPath xpath = xpathFactory.newXPath();

        // Construct the XPath expression using the provided xpath_id_value
        // The requirement is to query for /tag[@id='xpath'] where 'xpath' is the value from the request.
        String expression = "/tag[@id='" + xpath_id_value + "']";

        // Evaluate the XPath expression
        NodeList nodeList = (NodeList) xpath.evaluate(expression, doc, XPathConstants.NODESET);

        // Build the result string
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < nodeList.getLength(); i++) {
            result.append(nodeList.item(i).getTextContent());
            if (i < nodeList.getLength() - 1) {
                result.append("\n"); // Or any other desired separator
            }
        }

        return result.toString();
    }
}
