import org.w3c.dom.NodeList;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Ambil sumber XML dari permintaan menggunakan 'xml_src' dan lakukan parsing.
     * Ambil xpath dari permintaan menggunakan 'xpath' dan kueri XML menggunakan xpath untuk /tag[@id='xpath'].
     * :retur: Hasil dari kueri.
     */
    public NodeList queryXml(String xml_src, String xpathExpression) throws Exception {
        // Parse XML source
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new ByteArrayInputStream(xml_src.getBytes(StandardCharsets.UTF_8)));

        // Create XPath object
        XPathFactory xpathFactory = XPathFactory.newInstance();
        XPath xpath = xpathFactory.newXPath();

        // Query XML using XPath
        // The problem description implies the xpathExpression should be used to construct a specific XPath.
