import java.io.StringReader;
import java.io.StringWriter;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamResult;
import javax.xml.transform.stream.StreamSource;

public class ClassX {
    /**
     * Get XML source from the request using 'xml' key and parse it.
     * Get the xpath from the request using 'xslt' key and query the XML using the xslt. 
     * :return: The result of the query.
     */
    public String transformXmlWithXslt(String xml, String xslt) throws Exception {
        TransformerFactory factory = TransformerFactory.newInstance();

        // Use the XSLT string as the stylesheet source
        StreamSource xsltSource = new StreamSource(new StringReader(xslt));
        Transformer transformer = factory.newTransformer(xsltSource);

        // Use the XML string as the input source
        StreamSource xmlSource = new StreamSource(new StringReader(xml));

        // Prepare a StringWriter to capture the transformation result
        StringWriter writer = new StringWriter();
        StreamResult result = new StreamResult(writer);

        // Perform the transformation
        transformer.transform(xmlSource, result);

        // Return the transformed XML as a string
        return writer.toString();
    }
}
