import java.io.StringReader;
import java.io.StringWriter;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamResult;
import javax.xml.transform.stream.StreamSource;

public class ClassX {
    /**
     * احصل على مصدر XML من الطلب باستخدام مفتاح 'xml' وقم بتحليله.
     * احصل على xpath من الطلب باستخدام مفتاح 'xslt' واستعلم عن XML باستخدام xslt.
     * :النتيجة: نتيجة الاستعلام.
     */
    public String transformXml(String xmlSource, String xsltSource) throws Exception {
        // Create a TransformerFactory
        TransformerFactory factory = TransformerFactory.newInstance();

        // Create a Transformer for the XSLT stylesheet
        Transformer transformer = factory.newTransformer(new StreamSource(new StringReader(xsltSource)));

        // Prepare the XML source
        StreamSource xmlInput = new StreamSource(new StringReader(xmlSource));

        // Prepare the output
        StringWriter writer = new StringWriter();
        StreamResult xmlOutput = new StreamResult(writer);

        // Perform the transformation
        transformer.transform(xmlInput, xmlOutput);

        // Return the transformed XML as a String
        return writer.toString();
    }
}
