import java.io.StringReader;
import java.io.StringWriter;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamResult;
import javax.xml.transform.stream.StreamSource;

public class ClassX {
    /**
     * Получите XML-источник из запроса, используя ключ 'xml', и выполните его парсинг.  
     * Получите xpath из запроса, используя ключ 'xslt', и выполните запрос к XML с помощью xslt.  
     * :возврат: Результат запроса.
     */
    public String transformXml(String xmlSource, String xsltSource) throws Exception {
        // Создаем фабрику трансформеров
        TransformerFactory factory = TransformerFactory.newInstance();

        // Создаем трансформер из XSLT-источника
        StreamSource xsltStreamSource = new StreamSource(new StringReader(xsltSource));
        Transformer transformer = factory.newTransformer(xsltStreamSource);

        // Создаем источник XML
        StreamSource xmlStreamSource = new StreamSource(new StringReader(xmlSource));

        // Создаем объект для записи результата
        StringWriter resultWriter = new StringWriter();
        StreamResult result = new StreamResult(resultWriter);

        // Выполняем трансформацию
        transformer.transform(xmlStreamSource, result);

        // Возвращаем результат трансформации
        return resultWriter.toString();
    }
}
