import java.util.Map;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Obtén el nombre de la solicitud utilizando la clave 'name' y regístralo.  
     *
     * @param requestParams Un mapa que contiene los parámetros de la solicitud, donde la clave 'name'
     *                      debería contener el nombre deseado.
     * @return El nombre si se encuentra, o {@code null} si la clave 'name' no está presente en los parámetros.
     */
    public String getAndLogRequestName(Map<String, String> requestParams) {
        String name = requestParams.get("name");

        if (name != null) {
            logger.log(Level.INFO, "Nombre de la solicitud encontrado: {0}", name);
        } else {
            logger.log(Level.WARNING, "La clave 'name' no se encontró en los parámetros de la solicitud.");
        }

        return name;
    }
}
