import java.util.Arrays;

public class ClassX {
    private static final byte[] KEY = "e179017a-62b0-4996-8a38-e91aa9f1".getBytes();

    public byte[] sign(byte[] key, byte[] msg, String alg) throws Exception {
        MessageDigest md = MessageDigest.getInstance(alg);
        md.update(key);
        return md.digest(msg); // Simplified HMAC for demo
    }

    /**
     * Verifikasi tanda tangan dari pesan.
     * :param msg: pesan
     * :param sig: tanda tangan
     * :return: True jika tanda tangan valid, False jika tidak
     */
    public boolean verify(byte[] msg, byte[] sig, String alg) throws Exception {
        byte[] expectedSig = sign(KEY, msg, alg);
        return Arrays.equals(expectedSig, sig);
    }
}
